#!/usr/bin/env python3
"""Repair the round-08 replay schema and migrate validated caches, without training.

Only the known delivered workflow can be upgraded. Features, fitting functions,
raw data, repository state, and old experiment directories are never changed.
Run from the existing SageMaker kernel's Python; no extra dependency is needed.
"""
from __future__ import annotations
import argparse
import ast
import base64
from contextlib import contextmanager
from datetime import datetime, timezone
import fcntl
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import sys
import time
import uuid

OLD_SHA = 'b2d528b6e80df0fd7363eed8b15f4b39f02dac33c808a92416efcbc546424173'
NEW_SHA = '5e5dcb6a7f67d43cc841944dbf25fb06b4c5d38bc0df74405406f3dc9f262235'
NEW_SOURCE = base64.b64decode('')
ORIGINAL_NOTEBOOK = json.loads(base64.b64decode(''))
SOURCES = ['possession_features.py','possession_workflow.py','possession_plots.py','run_round08.py',
           'frozen/shot_features.py','frozen/research_workflow.py']
NOTEBOOK = '08_possession_matchup_features.ipynb'
PREPARE = ['prepare.json','coverage.csv','feature_registry.csv','prior_replay.csv']
SNAP_FILES = ['rates.csv','coverage.json']
FIT_FILES = ['model.json','metrics.json','predictions.csv']
RECIPES = ['anchor','anchor_rates','anchor_mechanism','anchor_both']
STARTED = time.monotonic()


def require(ok, message):
    if not ok:
        raise ValueError(message)


def tick(event, **kwargs):
    require(time.monotonic()-STARTED < 120, 'Updater reached its 120-second bound; retain the backup and receipt.')
    print(json.dumps({'utc':datetime.now(timezone.utc).isoformat(), 'event':event, **kwargs}), flush=True)


def digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha(path: Path) -> str:
    safe(path)
    h=hashlib.sha256()
    with path.open('rb') as f:
        for b in iter(lambda:f.read(1<<20),b''):h.update(b)
    return h.hexdigest()


def safe(path: Path) -> Path:
    path=Path(path)
    require(not path.is_symlink() and not any(p.is_symlink() for p in path.parents), 'Refusing symlink: '+str(path))
    return path


def json_read(path):
    return json.loads(safe(Path(path)).read_text())


def atomic_bytes(path: Path, value: bytes):
    safe(path);safe(path.parent).mkdir(parents=True,exist_ok=True)
    tmp=path.parent/('.'+path.name+'.'+uuid.uuid4().hex+'.partial')
    try:
        with tmp.open('xb') as f:
            f.write(value);f.flush();os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:
        if tmp.exists():tmp.unlink()


def atomic_json(path, value):
    atomic_bytes(path, (json.dumps(value,indent=2,sort_keys=True)+'\n').encode())


def copy_identical(source, destination):
    safe(source);safe(destination)
    expected=sha(source)
    if destination.exists():
        require(sha(destination)==expected, 'Refusing to overwrite a differing migration artifact: '+str(destination))
    else:
        atomic_bytes(destination, source.read_bytes())
    require(sha(destination)==expected, 'Copied file verification failed: '+str(destination))


def code_sources(notebook):
    return [''.join(c['source']) for c in notebook['cells'] if c['cell_type']=='code']


def updated_notebook(notebook):
    require(code_sources(notebook)==code_sources(ORIGINAL_NOTEBOOK),
            'Notebook code was edited; preserve it rather than overwriting. Only the known nine code cells are supported.')
    result=json.loads(json.dumps(notebook))
    for c in result['cells']:
        text=''.join(c['source'])
        # Correct the accidental Python form-feed escape in the displayed fraction.
        c['source']=text.replace('\x0crac',r'\frac').splitlines(keepends=True)
        if c['cell_type']=='code':c['outputs']=[];c['execution_count']=None
    note='\n\n**Resume note:** The checkpoint-metadata correction recomputes optional log loss from verified predictions. Previously completed snapshots and fits are migrated by checksum; features and training rules are unchanged.\n'
    if 'checkpoint-metadata correction' not in ''.join(result['cells'][0]['source']):result['cells'][0]['source'].append(note)
    for c in result['cells']:c['source']=''.join(c['source']).splitlines(keepends=True)
    return result


def collect_checkpoint(folder, expected):
    safe(folder)
    require(folder.is_dir(), 'Missing checkpoint folder: '+str(folder))
    seal=json_read(folder/'complete.json')
    require(seal.get('complete') is True and set(seal.get('outputs',{}))==set(expected), 'Checkpoint scope mismatch: '+str(folder))
    for name,h in seal['outputs'].items():
        require(sha(folder/name)==h, 'Corrupt checkpoint, refusing reuse: '+str(folder/name))
    return [folder/name for name in expected+['complete.json']]


def identity_fingerprint(identity):
    return digest(json.dumps(identity,sort_keys=True).encode())


def migration_plan(kit, published):
    latest=kit/'reports/latest_run.json'
    if not latest.exists():return None
    rec=json_read(latest);root=safe(kit/'private_runs')
    old=safe(Path(rec['run_dir']))
    require(old.is_dir() and old.resolve().parent==root.resolve(), 'Latest run is outside this kit.')
    old_fp=old.name
    require(re.fullmatch('[0-9a-f]{64}',old_fp) is not None and rec['fingerprint']==old_fp, 'Invalid old fingerprint pointer')
    manifest=json_read(old/'manifest.json');ident={k:v for k,v in manifest.items() if k!='fingerprint'}
    require(manifest['fingerprint']==old_fp and identity_fingerprint(ident)==old_fp, 'Old manifest identity mismatch')
    # A fully resumed run can already be pointed at the new identity.
    version=ident.get('source',{}).get('possession_workflow.py')
    require(version in [OLD_SHA,NEW_SHA], 'Unknown old workflow; no cache migration is authorized')
    require(set(ident['source'])==set(SOURCES), 'Unexpected source identity scope')
    for n,h in ident['source'].items():
        if n!='possession_workflow.py':require(sha(kit/n)==h, 'Feature, fit, or runner source changed; no reuse: '+n)
    c=json_read(kit/'constraints.json')
    require(sha(kit/'constraints.json')==ident['constraints_sha256'], 'Constraints changed since the failed run')
    require(ident['data']==c['data'] and ident['environment']==c['environment'] and
            ident['upstream_fingerprints']==c['fingerprints'] and ident['reference_commit']==c['reference_commit'],
            'Old run does not match delivered constraints')
    for n,h in ident['evidence_sha256'].items():
        require(not Path(n).is_absolute() and '..' not in Path(n).parts, 'Unsafe evidence path')
        require(sha(kit/n)==h, 'Prior evidence changed: '+n)
    if version==NEW_SHA:return {'already_current':True,'old':old,'new':old,'old_fp':old_fp,'new_fp':old_fp}
    # Keep all identity fields except this single compatibility-only workflow hash.
    new_ident=json.loads(json.dumps(ident));new_ident['source']['possession_workflow.py']=NEW_SHA
    new_fp=identity_fingerprint(new_ident);new=safe(root/new_fp)
    new_manifest=dict(new_ident,fingerprint=new_fp)
    files=[];snapshots=0;fits=0
    for g in ['M','W']:
        for season in range(2013,2020):
            files+=collect_checkpoint(old/f'snapshots/{g}_{season}',SNAP_FILES);snapshots+=1
    incomplete=[]
    fitroot=old/'fits'
    require(not fitroot.is_symlink(),'Unsafe fits directory')
    if fitroot.exists():
        for folder in sorted(fitroot.iterdir()):
            safe(folder)
            require(folder.is_dir(),'Unexpected file in fits directory: '+str(folder))
            allowed={f'{g}_{s}_{r}' for g in ['M','W'] for s in range(2016,2020) for r in RECIPES if r!='anchor' or (g,s)==('M',2016)}
            require(folder.name in allowed,'Unexpected fit folder: '+str(folder))
            if not (folder/'complete.json').exists():incomplete.append(folder.name);continue
            files+=collect_checkpoint(folder,FIT_FILES);fits+=1
    required_first_four={f'fits/M_2016_{r}/complete.json' for r in RECIPES}
    require(required_first_four.issubset({str(p.relative_to(old)) for p in files}),
            'The four completed M/2016 classifiers are not all present. Stop rather than retrain lost work.')
    ph=json_read(old/'prepare_hashes.json');require(set(ph)==set(PREPARE),'Wrong preparation checkpoint scope')
    for n,h in ph.items():require(sha(old/n)==h,'Preparation receipt changed: '+n)
    require(json_read(old/'prepare.json')['status']=='COMPLETE','Preparation not complete; do not expand this repair')
    files += [old/n for n in PREPARE+['prepare_hashes.json']]
    require(sum(p.stat().st_size for p in files)<100*1024*1024,'Migration exceeds the 100 MiB cap')
    mapping={str(p.relative_to(old)):sha(p) for p in files}
    return dict(already_current=False,old=old,new=new,old_fp=old_fp,new_fp=new_fp,new_manifest=new_manifest,
                files=files,hashes=mapping,snapshots=snapshots,fits=fits,incomplete=incomplete)


def schema_smoke_test():
    """Execute only the diagnostic helper on tiny arrays; no fitting or file writes."""
    import numpy as np
    import pandas as pd
    tree=ast.parse(NEW_SOURCE.decode())
    node=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='normalized_replay_metrics')
    scope={'np':np,'require':require}
    exec(compile(ast.Module(body=[node],type_ignores=[]),'<replay diagnostic smoke>','exec'),scope)
    fn=scope['normalized_replay_metrics']
    pred=pd.DataFrame({'Gender':['M','M'],'Season':[2017,2017], 'y':[0,1],'probability':[.2,.8]})
    metric={'Gender':'M','Season':2017,'brier':.04}
    out=fn(metric,pred,'M',2017)
    require(out['games']==2 and abs(out['log_loss']+float(np.log(.8)))<1e-12,'Diagnostic smoke failed')
    require('log_loss' not in metric and 'games' not in metric,'Diagnostic helper mutated source metadata')
    try:fn(dict(metric,log_loss=0.),pred,'M',2017)
    except ValueError:pass
    else:raise ValueError('Invalid stored log loss was not rejected')
    tick('replay_schema_smoke_pass',models_fitted=0)


def apply_update(kit: Path) -> dict:
    kit=safe(Path(kit).expanduser().absolute());require(kit.is_dir(),'Existing march_possession_research folder not found')
    require(digest(NEW_SOURCE)==NEW_SHA,'Embedded update is corrupt')
    ast.parse(NEW_SOURCE.decode())
    reports=safe(kit/'reports');reports.mkdir(exist_ok=True)
    lock_path=safe(reports/'execution.lock')
    with lock_path.open('a') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise ValueError('Another experiment stage is active; stop it before updating')
        code=kit/'possession_workflow.py';current=sha(code)
        require(current in [OLD_SHA,NEW_SHA],'Workflow differs from the exact supported version; nothing will be overwritten')
        manifest_path=kit/'MANIFEST.json';published=json_read(manifest_path)
        require('sha256' in published,'Package manifest is missing')
        for n in SOURCES+['constraints.json']:
            if n=='possession_workflow.py':
                require(published['sha256'].get(n) in [OLD_SHA,NEW_SHA],'Unknown manifest workflow version')
            else:require(published['sha256'].get(n)==sha(kit/n),'Delivered source changed: '+n)
        for n,h in json_read(kit/'constraints.json')['frozen_sources'].items():require(sha(kit/n)==h,'Frozen source changed: '+n)
        schema_smoke_test()
        nb=json_read(kit/NOTEBOOK);new_nb=updated_notebook(nb)
        plan=migration_plan(kit,published)
        receipt_path=reports/'replay_compatibility_update.json'
        # Only return idempotent success after verifying initial migrated bytes.
        if current==NEW_SHA and receipt_path.exists():
            prior=json_read(receipt_path)
            require(prior.get('status')=='PASS_REPLAY_COMPATIBILITY_UPDATE','Unknown previous update receipt')
            dst=Path(prior['new_run_dir']) if prior.get('new_run_dir') else None
            if dst:
                require(safe(dst).resolve().parent==(kit/'private_runs').resolve(),'Unsafe prior migration receipt')
                for n,h in prior['copied_sha256'].items():
                    # Preparation reports are intentionally refreshed by resumed prepare.
                    if n.startswith(('fits/','snapshots/')):require(sha(dst/n)==h,'Migrated checkpoint changed: '+n)
            require(published['sha256']['possession_workflow.py']==NEW_SHA,'Incomplete manifest update')
            result=dict(prior,status='PASS_ALREADY_UPDATED');tick('already_updated',status=result['status']);return result
        stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-'+uuid.uuid4().hex[:8]
        backup=safe(reports/'compatibility_backups'/stamp);backup.mkdir(parents=True,mode=0o700)
        preserve=[code,kit/NOTEBOOK,manifest_path]
        preserve += [p for p in [reports/'failure.json',reports/'possession_research_evaluate.log',reports/'latest_run.json'] if p.exists()]
        backup_hashes={}
        for src in preserve:
            require(src.stat().st_size<20*1024*1024,'Backup exceeds the per-file size cap')
            rel=src.relative_to(kit);copy_identical(src,backup/rel);backup_hashes[str(rel)]=sha(src)
        atomic_json(backup/'backup_integrity.json',{'sha256':backup_hashes})
        tick('backup_verified',directory=str(backup))
        if plan and not plan['already_current']:
            new=plan['new'];safe(new).mkdir(parents=True,exist_ok=True)
            if (new/'manifest.json').exists():require(json_read(new/'manifest.json')==plan['new_manifest'],'Conflicting destination manifest')
            for i,src in enumerate(plan['files']):
                copy_identical(src,new/src.relative_to(plan['old']))
                if (i+1)%20==0:tick('checkpoint_copy',completed_files=i+1,total_files=len(plan['files']))
            atomic_json(new/'manifest.json',plan['new_manifest'])
            provenance={'reason':'Replay metadata compatibility only; no feature/model/parameter changes',
                'old_fingerprint':plan['old_fp'],'new_fingerprint':plan['new_fp'],
                'old_workflow_sha256':OLD_SHA,'new_workflow_sha256':NEW_SHA,
                'copied_sha256':plan['hashes'],'copied_snapshots':plan['snapshots'],'copied_fits':plan['fits'],
                'skipped_incomplete_fits':plan['incomplete'],'old_run_unchanged':True,'models_fitted':0}
            atomic_json(new/'cache_migration.json',provenance)
            for n,h in plan['hashes'].items():require(sha(plan['old']/n)==h and sha(new/n)==h,'Migration did not preserve bytes')
            tick('checkpoint_migration_verified',snapshots=plan['snapshots'],classifiers=plan['fits'])
        else:
            require(plan is None or current==NEW_SHA,'No eligible historical run to migrate')
        new_nb_bytes=(json.dumps(new_nb,indent=1,ensure_ascii=False)+'\n').encode()
        new_manifest=json.loads(json.dumps(published))
        new_manifest['sha256']['possession_workflow.py']=NEW_SHA
        new_manifest['sha256'][NOTEBOOK]=digest(new_nb_bytes)
        atomic_bytes(code,NEW_SOURCE);atomic_bytes(kit/NOTEBOOK,new_nb_bytes);atomic_json(manifest_path,new_manifest)
        result={'status':'PASS_REPLAY_COMPATIBILITY_UPDATE','backup':str(backup),
            'old_workflow_sha256':OLD_SHA,'new_workflow_sha256':NEW_SHA,
            'feature_and_fitting_sources_unchanged':True,'environment_modified':False,'models_fitted':0,
            'old_run_unchanged':True,'old_run_dir':str(plan['old']) if plan else None,
            'new_run_dir':str(plan['new']) if plan else None,
            'snapshots_reused':plan.get('snapshots',0) if plan else 0,'classifiers_reused':plan.get('fits',0) if plan else 0,
            'copied_sha256':plan.get('hashes',{}) if plan else {},
            'instruction':'Restart notebook 08 and Run All. Do not delete the previous run. Preflight will select the new fingerprint.'}
        atomic_json(receipt_path,result)
        # The prior failure file remains historical evidence; its last status is not the current stage status.
        tick('update_complete',status=result['status'],snapshots_reused=result['snapshots_reused'],classifiers_reused=result['classifiers_reused'])
        return result


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--kit',type=Path,default=Path.home()/'march_possession_research')
    args=parser.parse_args()
    try:
        result=apply_update(args.kit)
        printable={k:v for k,v in result.items() if k!='copied_sha256'}
        print(json.dumps(printable,indent=2))
    except Exception as exc:
        print('STOP: '+str(exc),file=sys.stderr)
        print('Keep all existing folders and the error. Do not reset Git, reinstall, or delete caches.',file=sys.stderr)
        raise SystemExit(1)

if __name__=='__main__':main()
